String money(Object? v) => 'Rs. ${NumberFormat('#,##0.00').format((v as num?) ?? 0)}';
String iso(DateTime d) => DateFormat('yyyy-MM-dd').format(d);
double number(String s) => double.tryParse(s.replaceAll(',', '')) ?? 0;

class DashboardPage extends StatefulWidget { const DashboardPage({super.key}); @override State<DashboardPage> createState() => _DashboardPageState(); }
class _DashboardPageState extends State<DashboardPage> {
  late Future<Map<String, Object?>> data;
  @override void initState() { super.initState(); data = context.read<AppState>().repo.dashboard(); }
  @override Widget build(BuildContext context) => PageFrame(title: 'Dashboard', subtitle: DateFormat('EEEE, dd MMMM yyyy').format(DateTime.now()), actions: [IconButton(onPressed: () => setState(() => data = context.read<AppState>().repo.dashboard()), icon: const Icon(Icons.refresh))], child: FutureBuilder<Map<String, Object?>>(future: data, builder: (_, s) {
    if (!s.hasData) return const Center(child: CircularProgressIndicator()); final d = s.data!; final recent = d['recent'] as List<Map<String,Object?>>;
    return ListView(children: [Wrap(spacing: 14, runSpacing: 14, children: [
      Metric('Today’s collection', money(d['today']), Icons.payments, Colors.green), Metric('Outstanding', money(d['outstanding']), Icons.warning_amber, Colors.orange), Metric('Active students', '${d['students']}', Icons.school, Colors.blue), Metric('Active vehicles', '${d['vehicles']}', Icons.directions_bus, Colors.purple), Metric('Today’s trips', '${d['trips']}', Icons.route, Colors.teal),
    ]), const SizedBox(height: 22), Card(child: Padding(padding: const EdgeInsets.all(20), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Recent payments', style: TextStyle(fontSize: 18,fontWeight: FontWeight.bold)), const SizedBox(height: 12), if(recent.isEmpty) const SizedBox(height:150,child:EmptyState(Icons.receipt_long,'No payments yet')) else ...recent.map((r)=>ListTile(contentPadding:EdgeInsets.zero,leading:const CircleAvatar(child:Icon(Icons.check)),title:Text('${r['name']}  •  ${r['student_code']}'),subtitle:Text('${r['receipt_number']}  |  ${r['payment_date']}'),trailing:Text(money(r['amount']),style:const TextStyle(fontWeight:FontWeight.bold))))]))),
    ]);
  }));
}

class Metric extends StatelessWidget { final String label,value; final IconData icon; final Color color; const Metric(this.label,this.value,this.icon,this.color,{super.key}); @override Widget build(BuildContext context)=>SizedBox(width:220,height:122,child:Card(child:Padding(padding:const EdgeInsets.all(17),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[CircleAvatar(radius:18,backgroundColor:color.withValues(alpha:.12),child:Icon(icon,color:color,size:20)),const Spacer(),Text(value,style:const TextStyle(fontSize:21,fontWeight:FontWeight.bold)),Text(label,style:const TextStyle(color:Colors.grey,fontSize:12))])))); }

class StudentsPage extends StatefulWidget { const StudentsPage({super.key}); @override State<StudentsPage> createState()=>_StudentsPageState(); }
class _StudentsPageState extends State<StudentsPage>{
  String query=''; int? bus; late Future<List<Map<String,Object?>>> rows;
  @override void initState(){super.initState();reload();} void reload(){rows=context.read<AppState>().repo.students(query:query,vehicleId:bus);}
  @override Widget build(BuildContext context)=>PageFrame(title:'Students',subtitle:'Student profiles, bus groups, arrears and transfers',actions:[FilledButton.icon(onPressed:()=>editStudent(),icon:const Icon(Icons.add),label:const Text('Add student'))],child:Column(children:[
    Row(children:[Expanded(child:TextField(onChanged:(v){query=v;setState(reload);},decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Name, student ID or barcode...'))),const SizedBox(width:12),FutureBuilder(future:context.read<AppState>().repo.vehicles(),builder:(_,s)=>DropdownButton<int?>(value:bus,hint:const Text('All buses'),items:[const DropdownMenuItem(value:null,child:Text('All buses')),...?s.data?.map((v)=>DropdownMenuItem(value:v['id'] as int,child:Text('${v['vehicle_number']}')))],onChanged:(v)=>setState((){bus=v;reload();}))) ]),const SizedBox(height:14),
    Expanded(child:FutureBuilder<List<Map<String,Object?>>>(future:rows,builder:(_,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const EmptyState(Icons.school_outlined,'No students found');return Card(child:ListView.separated(itemCount:s.data!.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(_,i){final r=s.data![i];return ListTile(leading:CircleAvatar(child:Text('${r['name']}'.substring(0,1).toUpperCase())),title:Text('${r['name']}  •  ${r['student_code']}',style:const TextStyle(fontWeight:FontWeight.w600)),subtitle:Text('${r['vehicle_number']??'No bus'}  |  ${r['school']??''}  |  Grade ${r['grade']??'-'}'),trailing:Wrap(crossAxisAlignment:WrapCrossAlignment.center,children:[Text(money(r['outstanding']),style:TextStyle(color:(r['outstanding'] as num)>0?Colors.red:Colors.green,fontWeight:FontWeight.bold)),IconButton(onPressed:()=>editStudent(r),icon:const Icon(Icons.edit_outlined)),PopupMenuButton<String>(onSelected:(v)=>studentAction(v,r),itemBuilder:(_)=>[PopupMenuItem(value:'toggle',child:Text((r['is_active']==1)?'Deactivate':'Reactivate')),if(context.read<AppState>().canDelete)const PopupMenuItem(value:'delete',child:Text('Delete'))])]),onTap:()=>showStudent(r);};}));}))
  ]));
  Future<void> editStudent([Map<String,Object?>? row])async{final ok=await showDialog<bool>(context:context,builder:(_)=>StudentDialog(row:row));if(ok==true)setState(reload);}
  Future<void> studentAction(String a,Map<String,Object?> r)async{if(a=='toggle')await context.read<AppState>().repo.setStudentActive(r['id'] as int,r['is_active']!=1);else await context.read<AppState>().repo.deleteStudent(r['id'] as int);setState(reload);}
  void showStudent(Map<String,Object?> r)=>showDialog(context:context,builder:(_)=>AlertDialog(title:Text('${r['name']} — ${r['student_code']}'),content:SizedBox(width:520,child:FutureBuilder(future:context.read<AppState>().repo.ledger(r['id'] as int),builder:(_,s)=>ListView(shrinkWrap:true,children:[Text('Bus: ${r['vehicle_number']}\nSchool: ${r['school']}\nPickup: ${r['pickup_location']}\nWhatsApp: ${r['whatsapp_number']}\nMonthly fee: ${money(r['monthly_fee'])}\nOutstanding: ${money(r['outstanding'])}'),const SizedBox(height:18),const Text('Monthly ledger',style:TextStyle(fontWeight:FontWeight.bold)),...?s.data?.map((x)=>ListTile(dense:true,title:Text('${x['ledger_year']}-${('${x['ledger_month']}').padLeft(2,'0')}'),subtitle:Text('${x['status']}'),trailing:Text(money(x['balance_due']))))]))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Close'))]));
}

class StudentDialog extends StatefulWidget{final Map<String,Object?>? row;const StudentDialog({super.key,this.row});@override State<StudentDialog> createState()=>_StudentDialogState();}
class _StudentDialogState extends State<StudentDialog>{final form=GlobalKey<FormState>();late final Map<String,TextEditingController> c;int? vehicle;bool active=true;
  @override void initState(){super.initState();final r=widget.row??{};vehicle=r['vehicle_id'] as int?;active=r['is_active']!=0;c={for(final k in ['name','pickup_location','school','birth_year','grade','monthly_fee','whatsapp_number','phone_1','phone_2','previous_outstanding_balance'])k:TextEditingController(text:'${r[k]??''}')};}
  @override Widget build(BuildContext context)=>AlertDialog(title:Text(widget.row==null?'Add student':'Edit student'),content:SizedBox(width:640,child:Form(key:form,child:SingleChildScrollView(child:Wrap(spacing:12,runSpacing:12,children:[field('name','Student name',required:true),FutureBuilder(future:context.read<AppState>().repo.vehicles(),builder:(_,s)=>SizedBox(width:290,child:DropdownButtonFormField<int>(value:vehicle,decoration:const InputDecoration(labelText:'Bus / Vehicle'),items:s.data?.map((v)=>DropdownMenuItem(value:v['id'] as int,child:Text('${v['vehicle_number']}'))).toList(),onChanged:(v)=>setState(()=>vehicle=v),validator:(v)=>v==null?'Select a vehicle':null))),field('pickup_location','Pickup / Drop location'),field('school','School'),field('birth_year','Birth year',numeric:true),field('grade','Grade'),field('monthly_fee','Monthly fee',numeric:true),field('previous_outstanding_balance','Opening arrears',numeric:true),field('whatsapp_number','WhatsApp number'),field('phone_1','Phone 1'),field('phone_2','Phone 2'),SizedBox(width:290,child:SwitchListTile(title:const Text('Active student'),value:active,onChanged:(v)=>setState(()=>active=v)))])))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:save,child:const Text('Save'))]);
  Widget field(String k,String label,{bool required=false,bool numeric=false})=>SizedBox(width:290,child:TextFormField(controller:c[k],keyboardType:numeric?TextInputType.number:null,decoration:InputDecoration(labelText:label),validator:(v)=>required&&v!.trim().isEmpty?'Required':null));
  Future<void> save()async{if(!form.currentState!.validate()||vehicle==null)return;final d=<String,Object?>{for(final e in c.entries)e.key:e.value.text.trim(),'vehicle_id':vehicle,'is_active':active?1:0,'monthly_fee':number(c['monthly_fee']!.text),'previous_outstanding_balance':number(c['previous_outstanding_balance']!.text)};d['birth_year']=int.tryParse(c['birth_year']!.text);if('${d['grade']}'.isEmpty&&d['birth_year']!=null)d['grade']='${DateTime.now().year-(d['birth_year'] as int)-5}';await context.read<AppState>().repo.saveStudent(d,widget.row?['id'] as int?);if(mounted)Navigator.pop(context,true);}
}

class PaymentsPage extends StatefulWidget{const PaymentsPage({super.key});@override State<PaymentsPage> createState()=>_PaymentsPageState();}
class _PaymentsPageState extends State<PaymentsPage>{int? student;final amount=TextEditingController();final notes=TextEditingController();String method='Cash';DateTime date=DateTime.now();
 @override Widget build(BuildContext context)=>PageFrame(title:'Receive Payment',subtitle:'Automatic oldest-month-first allocation',child:ListView(children:[Card(child:Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Student and payment details',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:18),FutureBuilder(future:context.read<AppState>().repo.students(active:true),builder:(_,s)=>DropdownButtonFormField<int>(value:student,decoration:const InputDecoration(labelText:'Search / select student'),items:s.data?.map((r)=>DropdownMenuItem(value:r['id'] as int,child:Text('${r['student_code']} — ${r['name']} (${money(r['outstanding'])})'))).toList(),onChanged:(v)=>setState(()=>student=v))),const SizedBox(height:14),Row(children:[Expanded(child:TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount'))),const SizedBox(width:12),Expanded(child:DropdownButtonFormField(value:method,decoration:const InputDecoration(labelText:'Method'),items:['Cash','Card','Bank Transfer','Online','Other'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>method=v!)))]),const SizedBox(height:14),Row(children:[Expanded(child:TextField(controller:notes,decoration:const InputDecoration(labelText:'Remarks'))),const SizedBox(width:12),OutlinedButton.icon(onPressed:pickDate,icon:const Icon(Icons.calendar_month),label:Padding(padding:const EdgeInsets.all(12),child:Text(iso(date))))]),const SizedBox(height:20),FilledButton.icon(onPressed:pay,icon:const Icon(Icons.check_circle),label:const Padding(padding:EdgeInsets.all(12),child:Text('Confirm payment')))]))),const SizedBox(height:18),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Billing month',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:10),Text('Generate monthly fees for every active student. Skipped months are excluded.'),const SizedBox(height:12),FilledButton.tonalIcon(onPressed:generateMonth,icon:const Icon(Icons.calendar_view_month),label:const Text('Generate / advance billing month'))])))]));
 Future<void> pickDate()async{final d=await showDatePicker(context:context,firstDate:DateTime(2020),lastDate:DateTime(2100),initialDate:date);if(d!=null)setState(()=>date=d);}
 Future<void> pay()async{final value=number(amount.text);if(student==null||value<=0){toast('Select a student and enter an amount');return;}await context.read<AppState>().repo.makePayment(studentId:student!,amount:value,method:method,date:iso(date),notes:notes.text,userId:context.read<AppState>().user?['id'] as int?);amount.clear();notes.clear();setState(()=>student=null);toast('Payment saved successfully');}
 Future<void> generateMonth()async{final repo=context.read<AppState>().repo;var y=int.tryParse(await repo.setting('billing_year')??'')??DateTime.now().year;var m=int.tryParse(await repo.setting('billing_month')??'')??DateTime.now().month;m++;if(m==13){m=1;y++;}await repo.ensureLedger(y,m);toast('$y/$m billing generated');}
 void toast(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
}

