class MessagesPage extends StatefulWidget{const MessagesPage({super.key});@override State<MessagesPage> createState()=>_MessagesPageState();}
class _MessagesPageState extends State<MessagesPage>{int? bus;final message=TextEditingController(text:'හිතවත් දෙමාපියනි, මෙම මාසයේ පාසල් ප්‍රවාහන ගාස්තුව ගෙවීමට කාරුණික වන්න. ස්තූතියි.');
 @override Widget build(BuildContext context)=>PageFrame(title:'Messages',subtitle:'Bus-wise WhatsApp payment reminders',child:ListView(children:[Card(child:Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Broadcast filters',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:15),FutureBuilder(future:context.read<AppState>().repo.vehicles(),builder:(_,s)=>DropdownButtonFormField<int>(value:bus,decoration:const InputDecoration(labelText:'Bus'),items:s.data?.map((v)=>DropdownMenuItem(value:v['id'] as int,child:Text('${v['vehicle_number']}'))).toList(),onChanged:(v)=>setState(()=>bus=v))),const SizedBox(height:14),TextField(controller:message,maxLines:5,decoration:const InputDecoration(labelText:'Message')),const SizedBox(height:16),FilledButton.icon(onPressed:send,icon:const Icon(Icons.send),label:const Text('Open WhatsApp messages'))])))]));
 Future<void>send()async{if(bus==null)return;final rows=await context.read<AppState>().repo.students(vehicleId:bus,active:true);var opened=0;for(final r in rows){final phone='${r['whatsapp_number']??''}'.replaceAll(RegExp(r'[^0-9]'),'');if(phone.isEmpty)continue;final normalized=phone.startsWith('0')?'94${phone.substring(1)}':phone;final uri=Uri.parse('https://wa.me/$normalized?text=${Uri.encodeComponent(message.text.replaceAll('{name}','${r['name']}'))}');if(await canLaunchUrl(uri)){await launchUrl(uri,mode:LaunchMode.externalApplication);opened++;break;}}if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(opened==0?'No valid WhatsApp numbers':'Opened first message. Confirm send, then continue per student.')));}
}

class ReportsPage extends StatefulWidget{const ReportsPage({super.key});@override State<ReportsPage> createState()=>_ReportsPageState();}
class _ReportsPageState extends State<ReportsPage>{
 final defs=const [('Active Students','students'),('Payment History','payments'),('Vehicles','vehicles'),('Hiring & Profit','hiring'),('Audit Log','audit')];
 @override Widget build(BuildContext context)=>PageFrame(title:'Reports',subtitle:'Live reports and CSV exports',child:GridView.builder(gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:360,mainAxisExtent:155,crossAxisSpacing:14,mainAxisSpacing:14),itemCount:defs.length,itemBuilder:(_,i)=>Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.description_outlined,color:Theme.of(context).colorScheme.primary),const Spacer(),Text(defs[i].$1,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17)),Row(children:[const Text('CSV / Excel compatible',style:TextStyle(color:Colors.grey,fontSize:11)),const Spacer(),IconButton.filledTonal(onPressed:()=>export(defs[i]),icon:const Icon(Icons.download))])]))));
 Future<void>export((String,String) def)async{final repo=context.read<AppState>().repo;final rows=switch(def.$2){'students'=>await repo.students(),'payments'=>await repo.payments(),'vehicles'=>await repo.vehicles(),'hiring'=>await repo.hiring(),_=>await repo.audit()};if(rows.isEmpty)return;final csv=const ListToCsvConverter().convert([rows.first.keys.toList(),...rows.map((r)=>r.values.toList())]);final dir=await getApplicationDocumentsDirectory();final folder=Directory(p.join(dir.path,'Nethsara Reports'));await folder.create(recursive:true);final file=File(p.join(folder.path,'${def.$2}_${iso(DateTime.now())}.csv'));await file.writeAsString(csv);if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Saved: ${file.path}')));}
}

class SettingsPage extends StatefulWidget{const SettingsPage({super.key});@override State<SettingsPage> createState()=>_SettingsPageState();}
