 @override Widget build(BuildContext context)=>PageFrame(title:'Settings',subtitle:'Company, appearance, users and database',child:FutureBuilder(future:future,builder:(_,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(c.isEmpty)c={for(final k in keys)k:TextEditingController(text:s.data![k]??'')};return ListView(children:[Card(child:Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Company profile',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:15),Wrap(spacing:12,runSpacing:12,children:c.entries.map((e)=>SizedBox(width:310,child:TextField(controller:e.value,decoration:InputDecoration(labelText:e.key.replaceAll('_',' '))))).toList()),const SizedBox(height:16),FilledButton.icon(onPressed:save,icon:const Icon(Icons.save),label:const Text('Save settings'))]))),const SizedBox(height:14),Card(child:Column(children:[SwitchListTile(title:const Text('Dark mode'),subtitle:const Text('Change application appearance'),value:context.watch<AppState>().darkMode,onChanged:context.read<AppState>().setDark),const Divider(height:1),ListTile(leading:const Icon(Icons.backup),title:const Text('Backup database'),subtitle:const Text('Save a dated copy in Documents/Nethsara Backups'),trailing:const Icon(Icons.chevron_right),onTap:backup),ListTile(leading:const Icon(Icons.restore),title:const Text('Restore database'),subtitle:const Text('A safety backup is created first'),trailing:const Icon(Icons.chevron_right),onTap:restore),ListTile(leading:const Icon(Icons.system_update_alt),title:const Text('Import bundled v3.9 database'),subtitle:const Text('Use the original database included with this project'),trailing:const Icon(Icons.chevron_right),onTap:legacy)])),const SizedBox(height:14),if(context.read<AppState>().isAdmin)Card(child:ListTile(leading:const Icon(Icons.admin_panel_settings),title:const Text('Administrator tools'),subtitle:const Text('User/role management and audit logs are database-backed. Add a dedicated UI here if multiple staff accounts are needed.')))]);}));
 Future<void>save()async{await context.read<AppState>().repo.saveSettings({for(final e in c.entries)e.key:e.value.text});toast('Settings saved');}Future<void>backup()async{final path=await context.read<AppState>().db.backup();toast('Backup saved: $path');}Future<void>restore()async{final r=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['db']);if(r?.files.single.path!=null){await context.read<AppState>().db.restore(r!.files.single.path!);toast('Database restored. Restart the app.');}}Future<void>legacy()async{final path=await context.read<AppState>().db.extractBundledLegacy();await context.read<AppState>().db.restore(path);toast('v3.9 database imported. Restart the app.');}void toast(String x)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x)));
}

